    return EXIT_OK


def _run_correlate() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_CORRELATION_INPUT", "input payload must be a JSON object"
        )

    try:
        result = correlate_violations(
            payload.get("results"),
            payload.get("lineage"),
        )
    except InvalidCorrelationInputError as exc:
        return _emit_error("INVALID_CORRELATION_INPUT", str(exc))
    except UnknownCorrelationReferenceError as exc:
        return _emit_error("UNKNOWN_CORRELATION_REFERENCE", str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="dq",
        description="Data quality rule validation and lineage tracing.",
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    validate_parser = subparsers.add_parser(
        "validate",
        help="validate records from a UTF-8 JSON object on standard input",
    )
    validate_parser.set_defaults(handler=_run_validate)

    lineage_parser = subparsers.add_parser(
        "lineage",
        help="trace upstream/downstream lineage from a UTF-8 JSON object "
        "on standard input",
    )
    lineage_parser.set_defaults(handler=_run_lineage)

    field_lineage_parser = subparsers.add_parser(
        "field-lineage",
        help="trace upstream/downstream field-level lineage from a UTF-8 "
        "JSON object on standard input",
    )
    field_lineage_parser.set_defaults(handler=_run_field_lineage)

    lineage_paths_parser = subparsers.add_parser(
        "lineage-paths",
        help="explain ordered upstream/downstream lineage paths from a "
        "UTF-8 JSON object on standard input",
    )
    lineage_paths_parser.set_defaults(handler=_run_lineage_paths)

    field_lineage_paths_parser = subparsers.add_parser(
        "field-lineage-paths",
        help="explain ordered upstream/downstream field-level lineage paths "
        "from a UTF-8 JSON object on standard input",
    )
    field_lineage_paths_parser.set_defaults(handler=_run_field_lineage_paths)

    correlate_parser = subparsers.add_parser(
        "correlate",
        help="group violation results into cross-rule correlation events "
        "from a UTF-8 JSON object on standard input",
    )
    correlate_parser.set_defaults(handler=_run_correlate)
    return parser


def main(argv: Optional[List[str]] = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    return args.handler()


if __name__ == "__main__":
    sys.exit(main())

"""Field-level quality impact analysis over datasets, rules and samples.

The public entry point is :func:`analyze_field_impacts`. It combines a
field-level lineage graph with rule validation results and anomalous
samples: from every seed field it collects the fields reachable along at
least one directed edge (self-loops and cycles leading back to a seed
count as reachability), then reports the non-passing rules touching those
fields together with the anomalous samples that can actually be located.

Dangling edges (an endpoint referencing a dataset or field not declared
in ``datasets``) never abort the analysis: they are skipped during
traversal and written, sorted by their four endpoint keys, to
``unresolvedReferences``.

Structural problems raise :class:`ImpactInputError`, a :class:`ValueError`;
there is no partial result and no other business error.
"""

from __future__ import annotations

from collections import deque
from typing import Any, Dict, List, Set, Tuple

__all__ = [
    "analyze_field_impacts",
    "ImpactInputError",
]

_PAYLOAD_KEYS = frozenset(
    {
        "datasets",
        "lineageEdges",
        "validationResults",
        "anomalySamples",
        "seedFields",
    }
)
_EDGE_KEYS = frozenset(
    {"sourceDataset", "sourceField", "targetDataset", "targetField"}
)
_RULE_KEYS = frozenset(
    {"ruleId", "status", "fields", "failedSampleIds"}
)
_SAMPLE_KEYS = frozenset({"dataset", "fieldValues"})
_FIELD_REF_KEYS = frozenset({"dataset", "field"})
_VALID_STATUSES = frozenset({"passed", "failed", "skipped"})

# A field is identified by its (dataset, field) pair.
FieldId = Tuple[str, str]


class ImpactInputError(ValueError):
    """The impact-analysis payload is missing or malformed."""


def _error(message: str) -> ImpactInputError:
    return ImpactInputError(message)


def _check_keys(obj: Any, expected: frozenset, where: str) -> None:
    if not isinstance(obj, dict):
        raise _error(f"{where} must be an object")
    keys = set(obj)
    if keys != expected:
        missing = sorted(expected - keys)
        if missing:
            raise _error(f"{where} is missing keys: {missing}")
        unknown = sorted(keys - expected)
        raise _error(f"{where} has unsupported keys: {unknown}")


def _check_field_ref(ref: Any, where: str) -> FieldId:
    _check_keys(ref, _FIELD_REF_KEYS, where)
    dataset = ref["dataset"]
    field = ref["field"]
    if not isinstance(dataset, str) or not dataset:
        raise _error(f"{where}.dataset must be a non-empty string")
    if not isinstance(field, str) or not field:
        raise _error(f"{where}.field must be a non-empty string")
    return (dataset, field)


def _full_name(field_id: FieldId) -> str:
    return f"{field_id[0]}.{field_id[1]}"


def _name_path(path: Tuple[FieldId, ...]) -> Tuple[str, ...]:
    """Ordering view of a reference sequence: full names ``dataset.field``."""
    return tuple(_full_name(node) for node in path)


def _validate_datasets(datasets: Any) -> Set[FieldId]:
    """Validate ``datasets`` and return the declared fields.

    Duplicate datasets (as object keys they are already distinct) and
    duplicate field names are legal, so the declarations form a set.
    """
    if not isinstance(datasets, dict):
        raise _error(
            "datasets must be an object mapping dataset ids to field lists"
        )

    declared_fields: Set[FieldId] = set()
    for dataset, fields in datasets.items():
        if not isinstance(dataset, str) or not dataset:
            raise _error(
                f"datasets key must be a non-empty dataset id string: "
                f"{dataset!r}"
            )
        if not isinstance(fields, list):
            raise _error(
                f"datasets[{dataset!r}] must be a list of field ids"
            )
        for index, field in enumerate(fields):
            if not isinstance(field, str) or not field:
                raise _error(
                    f"datasets[{dataset!r}][{index}] must be a non-empty "
                    "field id string"
                )
            declared_fields.add((dataset, field))
    return declared_fields


def _validate_edges(
    edges: Any,
    declared_fields: Set[FieldId],
) -> Tuple[
    List[Tuple[FieldId, FieldId]],
    List[Dict[str, str]],
]:
    """Validate ``lineageEdges``.

    Returns the resolvable directed edges as ``(source, target)`` pairs and
    the dangling edges (an endpoint not declared in ``datasets``) as
    four-key dictionaries. Duplicate edges in either group are legal and
    deduplicated.
    """
    if not isinstance(edges, list):
        raise _error("lineageEdges must be a list")

    resolved_set: Set[Tuple[FieldId, FieldId]] = set()
    unresolved_set: Set[Tuple[str, str, str, str]] = set()

    for index, edge in enumerate(edges):
        _check_keys(edge, _EDGE_KEYS, f"lineageEdges[{index}]")
        source_dataset = edge["sourceDataset"]
        source_field = edge["sourceField"]
        target_dataset = edge["targetDataset"]
        target_field = edge["targetField"]
        for key, value in (
            ("sourceDataset", source_dataset),
            ("sourceField", source_field),
            ("targetDataset", target_dataset),
            ("targetField", target_field),
        ):
            if not isinstance(value, str) or not value:
                raise _error(
                    f"lineageEdges[{index}].{key} must be a non-empty string"
                )

        source = (source_dataset, source_field)
        target = (target_dataset, target_field)
        if source in declared_fields and target in declared_fields:
            resolved_set.add((source, target))
        else:
            unresolved_set.add(
                (source_dataset, source_field, target_dataset, target_field)
            )

    resolved = sorted(resolved_set, key=lambda pair: (_full_name(pair[0]), _full_name(pair[1])))
    unresolved = [
        {
            "sourceDataset": sd,
            "sourceField": sf,
            "targetDataset": td,
            "targetField": tf,
        }
        for sd, sf, td, tf in sorted(unresolved_set)
    ]
    return resolved, unresolved


def _validate_rules(rules: Any) -> List[Dict[str, Any]]:
    """Validate ``validationResults``.

    Rule field references must be structurally valid ``{dataset, field}``
    objects with non-empty identifiers; a reference to a field not declared
    in ``datasets`` is tolerated (it can never intersect a downstream set).
    """
    if not isinstance(rules, list):
        raise _error("validationResults must be a list")

    validated: List[Dict[str, Any]] = []
    for index, rule in enumerate(rules):
        _check_keys(rule, _RULE_KEYS, f"validationResults[{index}]")

        rule_id = rule["ruleId"]
        if not isinstance(rule_id, str) or not rule_id:
            raise _error(
                f"validationResults[{index}].ruleId must be a non-empty string"
            )

        status = rule["status"]
        if not isinstance(status, str) or status not in _VALID_STATUSES:
            raise _error(
                f"validationResults[{index}].status must be one of "
                f"{sorted(_VALID_STATUSES)}, got {status!r}"
            )

        raw_fields = rule["fields"]
        if not isinstance(raw_fields, list):
            raise _error(
                f"validationResults[{index}].fields must be a list"
            )
        fields: Set[FieldId] = set()
        for field_index, ref in enumerate(raw_fields):
            fields.add(
                _check_field_ref(
                    ref,
                    f"validationResults[{index}].fields[{field_index}]",
                )
            )

        failed_ids = rule["failedSampleIds"]
        if not isinstance(failed_ids, list):
            raise _error(
                f"validationResults[{index}].failedSampleIds must be a list"
            )
        for sample_index, sample_id in enumerate(failed_ids):
            if not isinstance(sample_id, str) or not sample_id:
                raise _error(
                    f"validationResults[{index}].failedSampleIds"
                    f"[{sample_index}] must be a non-empty string"
                )

        validated.append(
            {
                "ruleId": rule_id,
                "status": status,
                "fields": fields,
                "failedSampleIds": failed_ids,
            }
        )
    return validated


def _validate_samples(samples: Any) -> Set[str]:
    """Validate ``anomalySamples``; return the located sample ids.

    A sample id is locatable simply by being a key in ``anomalySamples``.
    """
    if not isinstance(samples, dict):
        raise _error(
            "anomalySamples must be an object mapping sample ids to samples"
        )

    for sample_id, sample in samples.items():
        if not isinstance(sample_id, str) or not sample_id:
            raise _error(
                f"anomalySamples key must be a non-empty sample id string: "
                f"{sample_id!r}"
            )
        _check_keys(sample, _SAMPLE_KEYS, f"anomalySamples[{sample_id!r}]")

        dataset = sample["dataset"]
        if not isinstance(dataset, str) or not dataset:
            raise _error(
                f"anomalySamples[{sample_id!r}].dataset must be a "
                "non-empty string"
            )

        field_values = sample["fieldValues"]
        if not isinstance(field_values, dict):
            raise _error(
                f"anomalySamples[{sample_id!r}].fieldValues must be an object"
            )
        for field_name in field_values:
            if not isinstance(field_name, str) or not field_name:
                raise _error(
                    f"anomalySamples[{sample_id!r}].fieldValues key must be "
                    f"a non-empty field id string: {field_name!r}"
                )
            # Values are any JSON value, including null; nothing to check.
    return set(samples)


def _validate_seeds(seeds: Any) -> List[FieldId]:
    """Validate ``seedFields`` and keep the original order (duplicates kept)."""
    if not isinstance(seeds, list):
        raise _error("seedFields must be a list")

    ordered: List[FieldId] = []
    for index, ref in enumerate(seeds):
        ordered.append(_check_field_ref(ref, f"seedFields[{index}]"))
    return ordered


def _shortest_paths(
    start: FieldId,
    outgoing: Dict[FieldId, List[FieldId]],
) -> Dict[FieldId, Tuple[FieldId, ...]]:
    """Shortest reference sequence from ``start`` to every field reachable
    along one or more edges.

    A plain BFS fixes the shortest distance of every field; the
    lexicographically smallest sequence of that length is then a dynamic
    program by increasing distance -- each field prepends the smallest
    sequence of a predecessor one edge closer. A self-loop or a longer
    cycle leading back to the seed also makes the seed reachable: its
    sequence is the smallest ``path(u) + (seed,)`` over every edge
    ``u -> seed``.
    """
    dist: Dict[FieldId, int] = {start: 0}
    queue = deque([start])
    while queue:
        current = queue.popleft()
        for nxt in outgoing.get(current, ()):
            if nxt not in dist:
                dist[nxt] = dist[current] + 1
                queue.append(nxt)

    # Incoming adjacency lets every field scan its predecessors.
    incoming: Dict[FieldId, List[FieldId]] = {}
    for source, targets in outgoing.items():
        for target in targets:
            incoming.setdefault(target, []).append(source)

    best: Dict[FieldId, Tuple[FieldId, ...]] = {start: (start,)}
    for depth in range(1, max(dist.values(), default=0) + 1):
        for field_id in (node for node, d in dist.items() if d == depth):
            candidates = [
                best[predecessor] + (field_id,)
                for predecessor in incoming.get(field_id, ())
                if dist.get(predecessor) == depth - 1
            ]
            best[field_id] = min(candidates, key=_name_path)

    paths = {node: best[node] for node in dist if node != start}

    # Any edge u -> start closes a cycle; the shortest one wins, then the
    # lexicographically smallest reference sequence.
    cycles = [
        best[node] + (start,)
        for node in incoming.get(start, ())
        if node != start
    ]
    self_loop = start in outgoing.get(start, ())
    if self_loop:
        cycles.append((start, start))
    if cycles:
        paths[start] = min(
            cycles, key=lambda sequence: (len(sequence), _name_path(sequence))
        )

    return paths


def analyze_field_impacts(payload: Any) -> Dict[str, Any]:
    """Analyze the downstream quality impact of a batch of seed fields.

    :param payload: object with exactly the keys ``datasets``,
        ``lineageEdges``, ``validationResults``, ``anomalySamples`` and
        ``seedFields``. ``datasets`` maps non-empty dataset ids to lists of
        non-empty field ids; ``lineageEdges`` lists ``{sourceDataset,
        sourceField, targetDataset, targetField}`` objects;
        ``validationResults`` lists ``{ruleId, status, fields,
        failedSampleIds}`` rules with ``status`` one of ``passed`` /
        ``failed`` / ``skipped`` and ``fields`` a list of ``{dataset,
        field}`` references declared in ``datasets``; ``anomalySamples``
        maps non-empty sample ids to ``{dataset, fieldValues}``;
        ``seedFields`` is a list of ``{dataset, field}`` references.
    :returns: ``{"status": "ok", "impacts": [...],
        "unresolvedReferences": [...]}``. ``impacts`` keeps the original
        ``seedFields`` order; each impact is ``{"seed", "downstreamFields",
        "affectedRules", "anomalySamples", "paths"}``. Downstream fields
        are the fields reachable along one or more resolvable directed
        edges (self-loops and edges back to the seed count), deduplicated
        and sorted by full name ``dataset.field``; rules are the
        non-``passed`` rules touching a downstream field, sorted by
        ``ruleId``; samples are the locatable ids (those present in
        ``anomalySamples``) among their ``failedSampleIds``, sorted
        ascending; ``paths`` holds one reference sequence per downstream
        field in the same ascending full-name order, each the shortest
        chain of ``{dataset, field}`` refs from the seed to that field
        (ties broken lexicographically). Dangling edges are skipped
        during traversal and listed (four keys, sorted) in
        ``unresolvedReferences``. An unknown seed has an empty impact; an
        empty ``seedFields`` yields an empty ``impacts`` while dangling
        edges are still reported.
    :raises ValueError: :class:`ImpactInputError` on any malformed payload.
    """
    _check_keys(payload, _PAYLOAD_KEYS, "payload")

    declared_fields = _validate_datasets(payload["datasets"])
    resolved_edges, unresolved = _validate_edges(
        payload["lineageEdges"], declared_fields
    )
    rules = _validate_rules(payload["validationResults"])
    locatable_samples = _validate_samples(payload["anomalySamples"])
    seeds = _validate_seeds(payload["seedFields"])

    outgoing: Dict[FieldId, List[FieldId]] = {}
    for source, target in resolved_edges:
        outgoing.setdefault(source, []).append(target)

    impacts: List[Dict[str, Any]] = []
    for seed in seeds:
        if seed not in declared_fields:
            shortest: Dict[FieldId, Tuple[FieldId, ...]] = {}
        else:
            shortest = _shortest_paths(seed, outgoing)

        downstream = set(shortest)
        downstream_names = sorted(downstream, key=_full_name)

        # Qualifying rules are non-passed rules that touch at least one
        # downstream field; affectedRules lists their ids (deduped) and
        # anomalySamples the locatable ids among their failedSampleIds.
        qualifying = [
            rule
            for rule in rules
            if rule["status"] != "passed" and rule["fields"] & downstream
        ]
        affected_rule_ids = sorted(
            {rule["ruleId"] for rule in qualifying}
        )
        anomaly_samples = sorted(
            {
                sample_id
                for rule in qualifying
                for sample_id in rule["failedSampleIds"]
                if sample_id in locatable_samples
            }
        )

        # One reference sequence per downstream field, in the same
        # ascending full-name order as ``downstreamFields``: each is the
        # shortest chain of {dataset, field} refs from the seed to that
        # field, ties broken lexicographically.
        paths = [
            [
                {"dataset": node[0], "field": node[1]}
                for node in shortest[field_id]
            ]
            for field_id in downstream_names
        ]

        impacts.append(
            {
                "seed": {"dataset": seed[0], "field": seed[1]},
                "downstreamFields": [
                    {"dataset": field_id[0], "field": field_id[1]}
                    for field_id in downstream_names
                ],
                "affectedRules": affected_rule_ids,
                "anomalySamples": anomaly_samples,
                "paths": paths,
            }
        )

    return {
        "status": "ok",
        "impacts": impacts,
        "unresolvedReferences": unresolved,
    }

"""End-to-end tests for the ``dq validate`` command line interface."""

import json
import subprocess
import sys
import unittest


PKG = [sys.executable, "-m", "data_quality", "validate"]


def run_cli(payload_bytes):
    return subprocess.run(
        PKG,
        input=payload_bytes,
        capture_output=True,
    )


def run_json(obj):
    return run_cli(
        json.dumps(obj, ensure_ascii=False).encode("utf-8")
    )


class CliSuccessTest(unittest.TestCase):
    def test_pass_and_fail_payloads(self):
        proc = run_json(
            {
                "records": [
                    {"id": "r1", "name": "甲"},
                    {"id": "r2", "name": "乙"},
                ],
                "rules": [
                    {"id": "req", "type": "required", "options": {"field": "name"}}
                ],
            }
        )
        self.assertEqual(proc.returncode, 0, proc.stderr)
        result = json.loads(proc.stdout.decode("utf-8"))
        self.assertTrue(result["passed"])
        self.assertEqual(result["violations"], [])
        self.assertEqual(result["summary"]["record_count"], 2)

        proc = run_json(
            {
                "records": [{"id": "r1"}, {"id": "r2", "name": "乙"}],
                "rules": [
                    {"id": "req", "type": "required", "options": {"field": "name"}}
                ],
            }
        )
        self.assertEqual(proc.returncode, 0)
        result = json.loads(proc.stdout.decode("utf-8"))
        self.assertFalse(result["passed"])
        self.assertEqual(result["violations"][0]["record_index"], 0)

    def test_utf8_round_trip(self):
        proc = run_json(
            {
                "records": [
                    {"id": "中文-id", "city": "北京"},
                    {"id": "x", "city": "广州"},
                ],
                "rules": [
                    {
                        "id": "cities",
                        "type": "allowed_values",
                        "options": {"field": "city", "values": ["北京", "上海"]},
                    }
                ],
            }
        )
        self.assertEqual(proc.returncode, 0, proc.stderr)
        result = json.loads(proc.stdout.decode("utf-8"))
        self.assertFalse(result["passed"])
        self.assertEqual(result["violations"][0]["record_id"], "x")
        self.assertEqual(result["violations"][0]["value"], "广州")
        # Non-ASCII is emitted literally, not escaped.
        self.assertIn("广州", proc.stdout.decode("utf-8"))


class CliErrorTest(unittest.TestCase):
    def _assert_error(self, proc, code):
        self.assertEqual(proc.returncode, 2, proc.stderr)
        body = json.loads(proc.stdout.decode("utf-8"))
        self.assertIn("error", body)
        self.assertEqual(body["error"]["code"], code)
        self.assertTrue(body["error"]["message"])

    def test_invalid_json(self):
        proc = run_cli(b"{not json")
        self._assert_error(proc, "INVALID_JSON")

    def test_invalid_utf8(self):
        proc = run_cli(b'{"records": [\xff]}')
        self._assert_error(proc, "INVALID_JSON")

    def test_payload_not_object(self):
        proc = run_json([1, 2])
        self._assert_error(proc, "INVALID_INPUT")

    def test_missing_keys(self):
        proc = run_json({"records": []})
        self._assert_error(proc, "INVALID_INPUT")
        proc = run_json({"rules": []})
        self._assert_error(proc, "INVALID_INPUT")

    def test_bad_records(self):
        proc = run_json({"records": [1], "rules": []})
        self._assert_error(proc, "INVALID_INPUT")

    def test_bad_rule(self):
        proc = run_json(
            {
                "records": [],
                "rules": [{"id": "r", "type": "mystery", "options": {}}],
            }
        )
        self._assert_error(proc, "INVALID_RULE")

    def test_duplicate_rule_id(self):
        proc = run_json(
            {
                "records": [],
                "rules": [
                    {"id": "r", "type": "required", "options": {"field": "a"}},
                    {"id": "r", "type": "required", "options": {"field": "b"}},
                ],
            }
        )
        self._assert_error(proc, "INVALID_RULE")

    def test_range_conflict(self):
        proc = run_json(
            {
                "records": [],
                "rules": [
                    {
                        "id": "r",
                        "type": "range",
                        "options": {"field": "a", "min": 9, "max": 1},
                    }
                ],
            }
        )
        self._assert_error(proc, "INVALID_RULE")

    def test_bad_regex(self):
        proc = run_json(
            {
                "records": [],
                "rules": [
                    {
                        "id": "r",
                        "type": "regex",
                        "options": {"field": "a", "pattern": "("},
                    }
                ],
            }
        )
        self._assert_error(proc, "INVALID_RULE")


if __name__ == "__main__":
    unittest.main()

input.content:
"""Cross-field composite consistency rules.

The public entry points are:

* :func:`register_composite_rules` -- register (compile) a set of
  cross-field rules, rejecting every definition whose per-record result
  cannot be determined. Registration is all-or-nothing.
* :func:`evaluate_composite_rules` -- evaluate the registered rules over
  records, one conclusion per (record, rule) pair.
* :func:`query_composite_results` -- filter complete evaluation results by
  ``rule_id``, severity and record locator in stable order.
* :func:`composite_results_to_correlation` /
  :func:`composite_results_to_impact_inputs` -- adapt failed composite
  results to the existing anomaly-sample correlation and field-impact
  input shapes without changing those entry points.

A composite rule relates several fields of the *same* record. Four
condition types are supported and may be combined with AND:

* ``field_equal``        -- two fields carry JSON-equal values
* ``field_not_equal``    -- two fields carry non-equal values
* ``date_before``        -- one date field is strictly before another
* ``required_when``      -- a field must be present and non-null while a
                            prerequisite field equals a given value

Every error subclasses :class:`~data_quality.validator.DataQualityError`
(itself a :class:`ValueError`) and carries a stable ``code`` plus the
offending ``rule_id`` / ``field_name`` where applicable.
"""

from __future__ import annotations

from datetime import date
from typing import Any, Dict, List, Optional, Set, Tuple

from .validator import DataQualityError

__all__ = [
    "register_composite_rules",
    "evaluate_composite_rules",
    "query_composite_results",
    "composite_results_to_correlation",
    "composite_results_to_impact_inputs",
    "sample_id_for_record",
    "CompositeRuleSetError",
    "DuplicateRuleIdError",
    "InvalidSeverityError",
    "UnsupportedCompositeConditionError",
    "InvalidCompositeRuleError",
    "InvalidRecordReferenceError",
    "SEVERITIES",
    "CONDITION_TYPES",
    "STATUS_PASSED",
    "STATUS_FAILED",
    "STATUS_SKIPPED_MISSING_FIELD",
]

SEVERITIES = ("error", "warning", "info")

CONDITION_EQUAL = "field_equal"
CONDITION_NOT_EQUAL = "field_not_equal"
CONDITION_DATE_BEFORE = "date_before"
CONDITION_REQUIRED_WHEN = "required_when"
CONDITION_TYPES = (
    CONDITION_EQUAL,
    CONDITION_NOT_EQUAL,
    CONDITION_DATE_BEFORE,
    CONDITION_REQUIRED_WHEN,
)

STATUS_PASSED = "PASSED"
STATUS_FAILED = "FAILED"
STATUS_SKIPPED_MISSING_FIELD = "SKIPPED_MISSING_FIELD"

_RULE_KEYS = frozenset({"rule_id", "fields", "conditions", "severity"})
_BINARY_FIELD_KEYS = ("left_field", "right_field")
_DATE_FIELD_KEYS = ("earlier_field", "later_field")


class CompositeRuleSetError(DataQualityError):
    """The composite rule set itself is empty or structurally unusable."""

    code = "INVALID_RULE_SET"

    def __init__(self, message: str, rule_id: Optional[str] = None):
        super().__init__(message)
        self.rule_id = rule_id
        self.field_name = None


class DuplicateRuleIdError(CompositeRuleSetError):
    """A ``rule_id`` appears more than once in the same rule set."""

    code = "DUPLICATE_RULE_ID"

    def __init__(self, rule_id: str):
        super().__init__(f"duplicate composite rule id: {rule_id!r}", rule_id)


class InvalidSeverityError(CompositeRuleSetError):
    """A rule carries a severity outside the supported vocabulary."""

    code = "INVALID_SEVERITY"

    def __init__(self, rule_id: str, severity: Any):
        super().__init__(
            f"rule {rule_id!r}: severity must be one of "
            f"{list(SEVERITIES)}, got {severity!r}",
            rule_id,
        )
        self.field_name = "severity"


class UnsupportedCompositeConditionError(CompositeRuleSetError):
    """A condition declares a ``type`` that is not supported."""

    code = "UNSUPPORTED_COMPOSITE_CONDITION"

    def __init__(self, rule_id: str, condition_type: Any):
        super().__init__(
            f"rule {rule_id!r}: unsupported composite condition type: "
            f"{condition_type!r}",
            rule_id,
        )
        self.field_name = "type"


class InvalidCompositeRuleError(DataQualityError):
    """A rule definition is valid-looking but can never be executed.

    Carries the offending ``rule_id`` and a locatable ``field_name`` (the
    offending field reference, or a structural key such as ``fields`` /
    ``conditions``).
    """

    code = "INVALID_COMPOSITE_RULE"

    def __init__(self, rule_id: Any, field_name: str, message: str):
        full_message = f"rule {rule_id!r}: {message}"
        super().__init__(full_message)
        self.rule_id = rule_id
        self.field_name = field_name


class InvalidRecordReferenceError(DataQualityError):
    """A ``record_refs`` entry cannot be resolved to an input record."""

    code = "INVALID_RECORD_REFERENCE"

    def __init__(self, message: str):
        super().__init__(message)
        self.rule_id = None
        self.field_name = None


def _json_equal(left: Any, right: Any) -> bool:
    """JSON value equality (booleans never equal numbers)."""
    if isinstance(left, bool) or isinstance(right, bool):
        return isinstance(left, bool) and isinstance(right, bool) and left == right
    if isinstance(left, list) and isinstance(right, list):
        return len(left) == len(right) and all(
            _json_equal(a, b) for a, b in zip(left, right)
        )
    if isinstance(left, dict) and isinstance(right, dict):
        return left.keys() == right.keys() and all(
            _json_equal(left[k], right[k]) for k in left
        )
    return left == right


def _parse_date(value: Any) -> Optional[date]:
    """Parse a strict ``YYYY-MM-DD`` calendar date; ``None`` if invalid."""
    if not isinstance(value, str) or len(value) != 10:
        return None
    if value[4] != "-" or value[7] != "-":
        return None
    try:
        return date.fromisoformat(value)
    except ValueError:
        return None


def _check_field_name(value: Any, rule_id: Any, where: str) -> str:
    if not isinstance(value, str) or not value:
        raise InvalidCompositeRuleError(
            rule_id, where, f"{where} must be a non-empty field name string"
        )
    return value


def _validate_condition(
    condition: Any,
    index: int,
    rule_id: Any,
    declared_fields: Set[str],
) -> Dict[str, Any]:
    """Validate one condition object and return its normalized form."""
    where = f"conditions[{index}]"
    if not isinstance(condition, dict):
        raise InvalidCompositeRuleError(
            rule_id, "conditions", f"{where} must be an object"
        )

    condition_type = condition.get("type")
    if "type" not in condition:
        raise InvalidCompositeRuleError(
            rule_id, "type", f"{where} is missing 'type'"
        )
    if not isinstance(condition_type, str):
        raise InvalidCompositeRuleError(
            rule_id, "type", f"{where}.type must be a string"
        )
    if condition_type not in CONDITION_TYPES:
        raise UnsupportedCompositeConditionError(rule_id, condition_type)

    def check_ref(key: str) -> str:
        if key not in condition:
            raise InvalidCompositeRuleError(
                rule_id, key, f"{where} is missing '{key}'"
            )
        field_name = _check_field_name(condition[key], rule_id, key)
        if field_name not in declared_fields:
            raise InvalidCompositeRuleError(
                rule_id,
                field_name,
                f"{where}.{key} references field {field_name!r} that is "
                f"not declared in the rule's field set",
            )
        return field_name

    if condition_type in (CONDITION_EQUAL, CONDITION_NOT_EQUAL):
        unknown = set(condition) - {"type", *_BINARY_FIELD_KEYS}
        if unknown:
            raise InvalidCompositeRuleError(
                rule_id,
                sorted(unknown)[0],
                f"{where} has unsupported keys: {sorted(unknown)}",
            )
        left_field = check_ref("left_field")
        right_field = check_ref("right_field")
        if left_field == right_field:
            raise InvalidCompositeRuleError(
                rule_id,
                right_field,
                f"{where} references the same field on both sides: "
                f"{left_field!r}",
            )
        return {
            "type": condition_type,
            "left_field": left_field,
            "right_field": right_field,
        }

    if condition_type == CONDITION_DATE_BEFORE:
        allowed = {"type", *_DATE_FIELD_KEYS}
        unknown = set(condition) - allowed
        if unknown:
            raise InvalidCompositeRuleError(
                rule_id,
                sorted(unknown)[0],
                f"{where} has unsupported keys: {sorted(unknown)}",
            )
        earlier_field = check_ref("earlier_field")
        later_field = check_ref("later_field")
        if earlier_field == later_field:
            raise InvalidCompositeRuleError(
                rule_id,
                later_field,
                f"{where} references the same field on both sides: "
                f"{earlier_field!r}",
            )
        return {
            "type": condition_type,
            "earlier_field": earlier_field,
            "later_field": later_field,
        }

    # required_when
    allowed = {"type", "when_field", "equals", "required_field"}
    unknown = set(condition) - allowed
    if unknown:
        raise InvalidCompositeRuleError(
            rule_id,
            sorted(unknown)[0],
            f"{where} has unsupported keys: {sorted(unknown)}",
        )
    when_field = check_ref("when_field")
    required_field = check_ref("required_field")
    if when_field == required_field:
        raise InvalidCompositeRuleError(
            rule_id,
            required_field,
            f"{where}.required_field must differ from when_field: "
            f"{when_field!r}",
        )
    # ``equals`` is optional; default null. Any JSON value is allowed.
    equals = condition["equals"] if "equals" in condition else None
    return {
        "type": condition_type,
        "when_field": when_field,
        "equals": equals,
        "required_field": required_field,
    }


def _compile_rule(rule: Any, seen_ids: Set[str]) -> Dict[str, Any]:
    if not isinstance(rule, dict):
        raise CompositeRuleSetError("each composite rule must be an object")

    keys = set(rule)
    missing = sorted(_RULE_KEYS - keys)
    if missing:
        field_name = missing[0]
        raise InvalidCompositeRuleError(
            rule.get("rule_id"),
            field_name,
            f"rule is missing keys: {missing}",
        )
    unknown = sorted(keys - _RULE_KEYS)
    if unknown:
        raise InvalidCompositeRuleError(
            rule.get("rule_id"),
            unknown[0],
            f"rule has unsupported keys: {unknown}",
        )

    rule_id = rule["rule_id"]
    if not isinstance(rule_id, str) or not rule_id:
        raise InvalidCompositeRuleError(
            rule_id, "rule_id", "rule_id must be a non-empty string"
        )
    if rule_id in seen_ids:
        raise DuplicateRuleIdError(rule_id)

    raw_fields = rule["fields"]
    if not isinstance(raw_fields, list) or not raw_fields:
        raise InvalidCompositeRuleError(
            rule_id,
            "fields",
            "fields must be a non-empty list of field name strings",
        )
    fields: List[str] = []
    for index, field_name in enumerate(raw_fields):
        checked = _check_field_name(
            field_name, rule_id, f"fields[{index}]"
        )
        if checked in fields:
            raise InvalidCompositeRuleError(
                rule_id,
                checked,
                f"field {checked!r} is listed more than once in the "
                f"rule's field set",
            )
        fields.append(checked)

    severity = rule["severity"]
    if not isinstance(severity, str) or severity not in SEVERITIES:
        raise InvalidSeverityError(rule_id, severity)

    raw_conditions = rule["conditions"]
    if not isinstance(raw_conditions, list) or not raw_conditions:
        raise InvalidCompositeRuleError(
            rule_id,
            "conditions",
            "conditions must be a non-empty list of condition objects",
        )

    declared_fields = set(fields)
    conditions = [
        _validate_condition(condition, index, rule_id, declared_fields)
        for index, condition in enumerate(raw_conditions)
    ]

    return {
        "rule_id": rule_id,
        "fields": fields,
        "severity": severity,
        "conditions": conditions,
    }


def register_composite_rules(
    dataset_id: Any, rules: Any
) -> Dict[str, Any]:
    """Register and compile a composite rule set.

    Registration is all-or-nothing: the first rule that cannot be executed
    deterministically aborts registration and no rule from the set is
    retained.

    :param dataset_id: non-empty dataset identifier string; echoed into
        every result.
    :param rules: non-empty list of rule objects, each with exactly the
        keys ``rule_id`` (non-empty unique string), ``fields`` (non-empty
        list of distinct non-empty field names the rule relates),
        ``severity`` (one of ``error`` / ``warning`` / ``info``) and
        ``conditions`` (non-empty list; every condition must reference
        fields declared in ``fields``).
    :returns: ``{"dataset_id": ..., "rules": [compiled rules]}`` preserving
        the input registration order.
    :raises ValueError: :class:`CompositeRuleSetError`
        (``INVALID_RULE_SET``), :class:`DuplicateRuleIdError`
        (``DUPLICATE_RULE_ID``), :class:`InvalidSeverityError`
        (``INVALID_SEVERITY``), :class:`UnsupportedCompositeConditionError`
        (``UNSUPPORTED_COMPOSITE_CONDITION``) or
        :class:`InvalidCompositeRuleError` (``INVALID_COMPOSITE_RULE``).
    """
    if not isinstance(dataset_id, str) or not dataset_id:
        raise CompositeRuleSetError(
            "dataset_id must be a non-empty string when composite rules "
            "are registered"
        )
    if not isinstance(rules, list) or not rules:
        raise CompositeRuleSetError(
            "composite rules must be a non-empty list"
        )

    compiled: List[Dict[str, Any]] = []
    seen_ids: Set[str] = set()
    for rule in rules:
        compiled_rule = _compile_rule(rule, seen_ids)
        seen_ids.add(compiled_rule["rule_id"])
        compiled.append(compiled_rule)

    return {"dataset_id": dataset_id, "rules": compiled}


def _condition_satisfied(condition: Dict[str, Any], record: Dict[str, Any]) -> bool:
    condition_type = condition["type"]

    if condition_type == CONDITION_EQUAL:
        return _json_equal(
            record[condition["left_field"]], record[condition["right_field"]]
        )

    if condition_type == CONDITION_NOT_EQUAL:
        return not _json_equal(
            record[condition["left_field"]], record[condition["right_field"]]
        )

    if condition_type == CONDITION_DATE_BEFORE:
        earlier = _parse_date(record[condition["earlier_field"]])
        later = _parse_date(record[condition["later_field"]])
        if earlier is None or later is None:
            # Illegal date values cannot satisfy a date-order constraint.
            return False
        return earlier < later

    # required_when: while the prerequisite holds, the required field
    # must be present (guaranteed by the field-set check) and non-null.
    if not _json_equal(record[condition["when_field"]], condition["equals"]):
        return True
    return record[condition["required_field"]] is not None


def _record_id(record: Dict[str, Any]) -> Any:
    return record["id"] if "id" in record else None


def _evaluate_one(
    record: Dict[str, Any],
    index: int,
    rule: Dict[str, Any],
    dataset_id: str,
) -> Dict[str, Any]:
    fields = rule["fields"]
    missing = [field for field in fields if field not in record]
    if missing:
        status = STATUS_SKIPPED_MISSING_FIELD
        condition_results = [
            {"type": condition["type"], "satisfied": None}
            for condition in rule["conditions"]
        ]
    else:
        condition_results = []
        satisfied_all = True
        for condition in rule["conditions"]:
            satisfied = _condition_satisfied(condition, record)
            condition_results.append(
                {"type": condition["type"], "satisfied": satisfied}
            )
            if not satisfied:
                satisfied_all = False
        status = STATUS_PASSED if satisfied_all else STATUS_FAILED

    return {
        "dataset_id": dataset_id,
        "record_index": index,
        "record_id": _record_id(record),
        "rule_id": rule["rule_id"],
        "fields": list(fields),
        "status": status,
        "severity": rule["severity"],
        "context": {
            # Snapshot only the participating fields, in registration
            # order, so downstream consumers see immutable evidence.
            "field_values": {
                field: record.get(field)
                for field in fields
                if field in record
            },
            "missing_fields": missing,
            "conditions": condition_results,
        },
    }


def _resolve_record_refs(
    record_refs: Any, records: List[Dict[str, Any]]
) -> List[Tuple[int, Dict[str, Any]]]:
    """Resolve record locators to ``(index, record)`` pairs.

    First occurrence wins (duplicate locators are deduplicated); the
    original reference order is preserved.
    """
    if not isinstance(record_refs, list):
        raise InvalidRecordReferenceError("record_refs must be a list")

    resolved: List[Tuple[int, Dict[str, Any]]] = []
    seen_indices: Set[int] = set()
    for ref_index, ref in enumerate(record_refs):
        where = f"record_refs[{ref_index}]"
        if not isinstance(ref, dict):
            raise InvalidRecordReferenceError(f"{where} must be an object")
        keys = set(ref)
        if not keys or not keys <= {"record_index", "record_id"}:
            raise InvalidRecordReferenceError(
                f"{where} may only contain 'record_index' and/or 'record_id'"
            )

        if "record_index" in ref:
            record_index = ref["record_index"]
            # bool is a subclass of int but JSON true/false are not indexes.
            if isinstance(record_index, bool) or not isinstance(record_index, int):
                raise InvalidRecordReferenceError(
                    f"{where}.record_index must be an integer"
                )
            if not 0 <= record_index < len(records):
                raise InvalidRecordReferenceError(
                    f"{where}.record_index is out of range: {record_index}"
                )
            index = record_index
        else:
            index = -1
            for candidate_index, candidate in enumerate(records):
                if "id" in candidate and candidate["id"] == ref["record_id"]:
                    index = candidate_index
                    break
            if index < 0:
                raise InvalidRecordReferenceError(
                    f"{where}.record_id does not match any record: "
                    f"{ref['record_id']!r}"
                )

        if "record_id" in ref:
            record_id = ref["record_id"]
            if not isinstance(record_id, str) or not record_id:
                raise InvalidRecordReferenceError(
                    f"{where}.record_id must be a non-empty string"
                )
            record = records[index]
            if record.get("id") != record_id or "id" not in record:
                raise InvalidRecordReferenceError(
                    f"{where} locates record index {index} but its record id "
                    f"is {record.get('id')!r}, not {record_id!r}"
                )

        if index not in seen_indices:
            seen_indices.add(index)
            resolved.append((index, records[index]))

    return resolved


def evaluate_composite_rules(
    records: Any,
    rule_set: Dict[str, Any],
    record_refs: Any = None,
) -> List[Dict[str, Any]]:
    """Evaluate registered composite rules over records.

    Records are read one by one; within one record every rule is evaluated
    in registration order. A record missing any field of a rule's target
    field set yields :data:`STATUS_SKIPPED_MISSING_FIELD` for that rule;
    the rule is neither passed nor failed for that record, and other rules
    keep executing.

    :param records: list of JSON object records.
    :param rule_set: output of :func:`register_composite_rules`.
    :param record_refs: optional list of locators (``{"record_index": i}``
        and/or ``{"record_id": ...}``) restricting evaluation to specific
        records; a locator that cannot be resolved raises
        :class:`InvalidRecordReferenceError`. When omitted every record is
        evaluated.
    :returns: complete result list, ordered by record order then by rule
        registration order.
    """
    if not isinstance(records, list):
        raise InvalidRecordReferenceError("records must be a list")
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            raise InvalidRecordReferenceError(
                f"records[{index}] must be a JSON object"
            )

    dataset_id = rule_set["dataset_id"]
    rules = rule_set["rules"]

    if record_refs is None:
        selected: List[Tuple[int, Dict[str, Any]]] = list(enumerate(records))
    else:
        selected = _resolve_record_refs(record_refs, records)

    results: List[Dict[str, Any]] = []
    for index, record in selected:
        for rule in rules:
            results.append(_evaluate_one(record, index, rule, dataset_id))
    return results


def query_composite_results(
    results: Any,
    rule_id: Any = None,
    severity: Any = None,
    record_index: Any = None,
    record_id: Any = None,
) -> Dict[str, Any]:
    """Filter complete composite results without changing their order.

    Every supplied filter is AND-combined; omitted filters do not restrict.

    :param results: result list produced by
        :func:`evaluate_composite_rules` (or a previously filtered one).
    :param rule_id: keep results of this rule id.
    :param severity: keep results with this severity level.
    :param record_index: keep results located at this record index.
    :param record_id: keep results located at this record id.
    :returns: ``{"count": n, "results": [...]}`` in the original stable
        order.
    """
    if not isinstance(results, list):
        raise ValueError("results must be a list")
    if rule_id is not None and not isinstance(rule_id, str):
        raise ValueError("rule_id filter must be a string")
    if severity is not None and not isinstance(severity, str):
        raise ValueError("severity filter must be a string")
    if record_index is not None and (
        isinstance(record_index, bool) or not isinstance(record_index, int)
    ):
        raise ValueError("record_index filter must be an integer")
    if record_id is not None and not isinstance(record_id, str):
        raise ValueError("record_id filter must be a string")

    filtered = []
    for result in results:
        if not isinstance(result, dict):
            raise ValueError("each result must be an object")
        if rule_id is not None and result.get("rule_id") != rule_id:
            continue
        if severity is not None and result.get("severity") != severity:
            continue
        if (
            record_index is not None
            and result.get("record_index") != record_index
        ):
            continue
        if record_id is not None and result.get("record_id") != record_id:
            continue
        filtered.append(result)

    return {"count": len(filtered), "results": filtered}


def sample_id_for_record(result: Dict[str, Any]) -> str:
    """Derive the stable anomaly-sample id used by the downstream adapters.

    A record's ``id`` is used when it is a non-empty string, otherwise a
    deterministic ``"record:<index>"`` locator. Evaluation results carry
    the same ``record_index`` / ``record_id`` pair, so jumping from a
    correlated anomaly back to the validation result resolves to the same
    record and participating fields.
    """
    record_id = result.get("record_id")
    if isinstance(record_id, str) and record_id:
        return record_id
    return f"record:{result['record_index']}"


def composite_results_to_correlation(
    results: Any,
) -> List[Dict[str, Any]]:
    """Adapt FAILED composite results to ``correlate_violations`` input.

    Emits one correlation result row per ``(failed rule result,
    participating field)`` with ``violated`` true and that field's value,
    so the existing cross-rule / field-lineage correlation consumes
    cross-field anomalies unchanged. PASSED and skipped results produce no
    rows.
    """
    if not isinstance(results, list):
        raise ValueError("results must be a list")

    rows: List[Dict[str, Any]] = []
    for result in results:
        if not isinstance(result, dict):
            raise ValueError("each result must be an object")
        if result.get("status") != STATUS_FAILED:
            continue
        sample_id = sample_id_for_record(result)
        values = result.get("context", {}).get("field_values", {})
        for field in result["fields"]:
            rows.append(
                {
                    "rule_id": result["rule_id"],
                    "dataset_id": result["dataset_id"],
                    "field_id": field,
                    "sample_id": sample_id,
                    "violated": True,
                    "value": values.get(field),
                }
            )
    return rows


def composite_results_to_impact_inputs(
    results: Any,
) -> Dict[str, Any]:
    """Adapt FAILED composite results to ``analyze_field_impacts`` inputs.

    :returns: ``{"validationResults": [...], "anomalySamples": {...}}``.
        Each failed rule becomes one ``failed`` validation result touching
        every participating ``{dataset, field}``; every failed record
        becomes a locatable anomaly sample keyed by the same sample id the
        correlation adapter uses, carrying the participating field values.
        The caller supplies ``datasets``, ``lineageEdges`` and
        ``seedFields`` to complete the impact-analysis payload.
    """
    if not isinstance(results, list):
        raise ValueError("results must be a list")

    rules_in_order: List[str] = []
    rule_fields: Dict[str, Set[Tuple[str, str]]] = {}
    rule_samples: Dict[str, List[str]] = {}
    samples: Dict[str, Dict[str, Any]] = {}

    for result in results:
        if not isinstance(result, dict):
            raise ValueError("each result must be an object")
        if result.get("status") != STATUS_FAILED:
            continue

        rule_id = result["rule_id"]
        if rule_id not in rule_fields:
            rules_in_order.append(rule_id)
            rule_fields[rule_id] = set()
            rule_samples[rule_id] = []
        dataset_id = result["dataset_id"]
        for field in result["fields"]:
            rule_fields[rule_id].add((dataset_id, field))

        sample_id = sample_id_for_record(result)
        if sample_id not in rule_samples[rule_id]:
            rule_samples[rule_id].append(sample_id)
        if sample_id not in samples:
            samples[sample_id] = {
                "dataset": dataset_id,
                "fieldValues": dict(
                    result.get("context", {}).get("field_values", {})
                ),
            }

    validation_results = [
        {
            "ruleId": rule_id,
            "status": "failed",
            "fields": [
                {"dataset": dataset, "field": field}
                for dataset, field in sorted(rule_fields[rule_id])
            ],
            "failedSampleIds": list(rule_samples[rule_id]),
        }
        for rule_id in rules_in_order
    ]

    return {
        "validationResults": validation_results,
        "anomalySamples": samples,
    }

toolUseResult.content:
"""Cross-field composite consistency rules.

The public entry points are:

* :func:`register_composite_rules` -- register (compile) a set of
  cross-field rules, rejecting every definition whose per-record result
  cannot be determined. Registration is all-or-nothing.
* :func:`evaluate_composite_rules` -- evaluate the registered rules over
  records, one conclusion per (record, rule) pair.
* :func:`query_composite_results` -- filter complete evaluation results by
  ``rule_id``, severity and record locator in stable order.
* :func:`composite_results_to_correlation` /
  :func:`composite_results_to_impact_inputs` -- adapt failed composite
  results to the existing anomaly-sample correlation and field-impact
  input shapes without changing those entry points.

A composite rule relates several fields of the *same* record. Four
condition types are supported and may be combined with AND:

* ``field_equal``        -- two fields carry JSON-equal values
* ``field_not_equal``    -- two fields carry non-equal values
* ``date_before``        -- one date field is strictly before another
* ``required_when``      -- a field must be present and non-null while a
                            prerequisite field equals a given value

Every error subclasses :class:`~data_quality.validator.DataQualityError`
(itself a :class:`ValueError`) and carries a stable ``code`` plus the
offending ``rule_id`` / ``field_name`` where applicable.
"""

from __future__ import annotations

from datetime import date
from typing import Any, Dict, List, Optional, Set, Tuple

from .validator import DataQualityError

__all__ = [
    "register_composite_rules",
    "evaluate_composite_rules",
    "query_composite_results",
    "composite_results_to_correlation",
    "composite_results_to_impact_inputs",
    "sample_id_for_record",
    "CompositeRuleSetError",
    "DuplicateRuleIdError",
    "InvalidSeverityError",
    "UnsupportedCompositeConditionError",
    "InvalidCompositeRuleError",
    "InvalidRecordReferenceError",
    "SEVERITIES",
    "CONDITION_TYPES",
    "STATUS_PASSED",
    "STATUS_FAILED",
    "STATUS_SKIPPED_MISSING_FIELD",
]

SEVERITIES = ("error", "warning", "info")

CONDITION_EQUAL = "field_equal"
CONDITION_NOT_EQUAL = "field_not_equal"
CONDITION_DATE_BEFORE = "date_before"
CONDITION_REQUIRED_WHEN = "required_when"
CONDITION_TYPES = (
    CONDITION_EQUAL,
    CONDITION_NOT_EQUAL,
    CONDITION_DATE_BEFORE,
    CONDITION_REQUIRED_WHEN,
)

STATUS_PASSED = "PASSED"
STATUS_FAILED = "FAILED"
STATUS_SKIPPED_MISSING_FIELD = "SKIPPED_MISSING_FIELD"

_RULE_KEYS = frozenset({"rule_id", "fields", "conditions", "severity"})
_BINARY_FIELD_KEYS = ("left_field", "right_field")
_DATE_FIELD_KEYS = ("earlier_field", "later_field")


class CompositeRuleSetError(DataQualityError):
    """The composite rule set itself is empty or structurally unusable."""

    code = "INVALID_RULE_SET"

    def __init__(self, message: str, rule_id: Optional[str] = None):
        super().__init__(message)
        self.rule_id = rule_id
        self.field_name = None


class DuplicateRuleIdError(CompositeRuleSetError):
    """A ``rule_id`` appears more than once in the same rule set."""

    code = "DUPLICATE_RULE_ID"

    def __init__(self, rule_id: str):
        super().__init__(f"duplicate composite rule id: {rule_id!r}", rule_id)


class InvalidSeverityError(CompositeRuleSetError):
    """A rule carries a severity outside the supported vocabulary."""

    code = "INVALID_SEVERITY"

    def __init__(self, rule_id: str, severity: Any):
        super().__init__(
            f"rule {rule_id!r}: severity must be one of "
            f"{list(SEVERITIES)}, got {severity!r}",
            rule_id,
        )
        self.field_name = "severity"


class UnsupportedCompositeConditionError(CompositeRuleSetError):
    """A condition declares a ``type`` that is not supported."""

    code = "UNSUPPORTED_COMPOSITE_CONDITION"

    def __init__(self, rule_id: str, condition_type: Any):
        super().__init__(
            f"rule {rule_id!r}: unsupported composite condition type: "
            f"{condition_type!r}",
            rule_id,
        )
        self.field_name = "type"


class InvalidCompositeRuleError(DataQualityError):
    """A rule definition is valid-looking but can never be executed.

    Carries the offending ``rule_id`` and a locatable ``field_name`` (the
    offending field reference, or a structural key such as ``fields`` /
    ``conditions``).
    """

    code = "INVALID_COMPOSITE_RULE"

    def __init__(self, rule_id: Any, field_name: str, message: str):
        full_message = f"rule {rule_id!r}: {message}"
        super().__init__(full_message)
        self.rule_id = rule_id
        self.field_name = field_name


class InvalidRecordReferenceError(DataQualityError):
    """A ``record_refs`` entry cannot be resolved to an input record."""

    code = "INVALID_RECORD_REFERENCE"

    def __init__(self, message: str):
        super().__init__(message)
        self.rule_id = None
        self.field_name = None


def _json_equal(left: Any, right: Any) -> bool:
    """JSON value equality (booleans never equal numbers)."""
    if isinstance(left, bool) or isinstance(right, bool):
        return isinstance(left, bool) and isinstance(right, bool) and left == right
    if isinstance(left, list) and isinstance(right, list):
        return len(left) == len(right) and all(
            _json_equal(a, b) for a, b in zip(left, right)
        )
    if isinstance(left, dict) and isinstance(right, dict):
        return left.keys() == right.keys() and all(
            _json_equal(left[k], right[k]) for k in left
        )
    return left == right


def _parse_date(value: Any) -> Optional[date]:
    """Parse a strict ``YYYY-MM-DD`` calendar date; ``None`` if invalid."""
    if not isinstance(value, str) or len(value) != 10:
        return None
    if value[4] != "-" or value[7] != "-":
        return None
    try:
        return date.fromisoformat(value)
    except ValueError:
        return None


def _check_field_name(value: Any, rule_id: Any, where: str) -> str:
    if not isinstance(value, str) or not value:
        raise InvalidCompositeRuleError(
            rule_id, where, f"{where} must be a non-empty field name string"
        )
    return value


def _validate_condition(
    condition: Any,
    index: int,
    rule_id: Any,
    declared_fields: Set[str],
) -> Dict[str, Any]:
    """Validate one condition object and return its normalized form."""
    where = f"conditions[{index}]"
    if not isinstance(condition, dict):
        raise InvalidCompositeRuleError(
            rule_id, "conditions", f"{where} must be an object"
        )

    condition_type = condition.get("type")
    if "type" not in condition:
        raise InvalidCompositeRuleError(
            rule_id, "type", f"{where} is missing 'type'"
        )
    if not isinstance(condition_type, str):
        raise InvalidCompositeRuleError(
            rule_id, "type", f"{where}.type must be a string"
        )
    if condition_type not in CONDITION_TYPES:
        raise UnsupportedCompositeConditionError(rule_id, condition_type)

    def check_ref(key: str) -> str:
        if key not in condition:
            raise InvalidCompositeRuleError(
                rule_id, key, f"{where} is missing '{key}'"
            )
        field_name = _check_field_name(condition[key], rule_id, key)
        if field_name not in declared_fields:
            raise InvalidCompositeRuleError(
                rule_id,
                field_name,
                f"{where}.{key} references field {field_name!r} that is "
                f"not declared in the rule's field set",
            )
        return field_name

    if condition_type in (CONDITION_EQUAL, CONDITION_NOT_EQUAL):
        unknown = set(condition) - {"type", *_BINARY_FIELD_KEYS}
        if unknown:
            raise InvalidCompositeRuleError(
                rule_id,
                sorted(unknown)[0],
                f"{where} has unsupported keys: {sorted(unknown)}",
            )
        left_field = check_ref("left_field")
        right_field = check_ref("right_field")
        if left_field == right_field:
            raise InvalidCompositeRuleError(
                rule_id,
                right_field,
                f"{where} references the same field on both sides: "
                f"{left_field!r}",
            )
        return {
            "type": condition_type,
            "left_field": left_field,
            "right_field": right_field,
        }

    if condition_type == CONDITION_DATE_BEFORE:
        allowed = {"type", *_DATE_FIELD_KEYS}
        unknown = set(condition) - allowed
        if unknown:
            raise InvalidCompositeRuleError(
                rule_id,
                sorted(unknown)[0],
                f"{where} has unsupported keys: {sorted(unknown)}",
            )
        earlier_field = check_ref("earlier_field")
        later_field = check_ref("later_field")
        if earlier_field == later_field:
            raise InvalidCompositeRuleError(
                rule_id,
                later_field,
                f"{where} references the same field on both sides: "
                f"{earlier_field!r}",
            )
        return {
            "type": condition_type,
            "earlier_field": earlier_field,
            "later_field": later_field,
        }

    # required_when
    allowed = {"type", "when_field", "equals", "required_field"}
    unknown = set(condition) - allowed
    if unknown:
        raise InvalidCompositeRuleError(
            rule_id,
            sorted(unknown)[0],
            f"{where} has unsupported keys: {sorted(unknown)}",
        )
    when_field = check_ref("when_field")
    required_field = check_ref("required_field")
    if when_field == required_field:
        raise InvalidCompositeRuleError(
            rule_id,
            required_field,
            f"{where}.required_field must differ from when_field: "
            f"{when_field!r}",
        )
    # ``equals`` is optional; default null. Any JSON value is allowed.
    equals = condition["equals"] if "equals" in condition else None
    return {
        "type": condition_type,
        "when_field": when_field,
        "equals": equals,
        "required_field": required_field,
    }


def _compile_rule(rule: Any, seen_ids: Set[str]) -> Dict[str, Any]:
    if not isinstance(rule, dict):
        raise CompositeRuleSetError("each composite rule must be an object")

    keys = set(rule)
    missing = sorted(_RULE_KEYS - keys)
    if missing:
        field_name = missing[0]
        raise InvalidCompositeRuleError(
            rule.get("rule_id"),
            field_name,
            f"rule is missing keys: {missing}",
        )
    unknown = sorted(keys - _RULE_KEYS)
    if unknown:
        raise InvalidCompositeRuleError(
            rule.get("rule_id"),
            unknown[0],
            f"rule has unsupported keys: {unknown}",
        )

    rule_id = rule["rule_id"]
    if not isinstance(rule_id, str) or not rule_id:
        raise InvalidCompositeRuleError(
            rule_id, "rule_id", "rule_id must be a non-empty string"
        )
    if rule_id in seen_ids:
        raise DuplicateRuleIdError(rule_id)

    raw_fields = rule["fields"]
    if not isinstance(raw_fields, list) or not raw_fields:
        raise InvalidCompositeRuleError(
            rule_id,
            "fields",
            "fields must be a non-empty list of field name strings",
        )
    fields: List[str] = []
    for index, field_name in enumerate(raw_fields):
        checked = _check_field_name(
            field_name, rule_id, f"fields[{index}]"
        )
        if checked in fields:
            raise InvalidCompositeRuleError(
                rule_id,
                checked,
                f"field {checked!r} is listed more than once in the "
                f"rule's field set",
            )
        fields.append(checked)

    severity = rule["severity"]
    if not isinstance(severity, str) or severity not in SEVERITIES:
        raise InvalidSeverityError(rule_id, severity)

    raw_conditions = rule["conditions"]
    if not isinstance(raw_conditions, list) or not raw_conditions:
        raise InvalidCompositeRuleError(
            rule_id,
            "conditions",
            "conditions must be a non-empty list of condition objects",
        )

    declared_fields = set(fields)
    conditions = [
        _validate_condition(condition, index, rule_id, declared_fields)
        for index, condition in enumerate(raw_conditions)
    ]

    return {
        "rule_id": rule_id,
        "fields": fields,
        "severity": severity,
        "conditions": conditions,
    }


def register_composite_rules(
    dataset_id: Any, rules: Any
) -> Dict[str, Any]:
    """Register and compile a composite rule set.

    Registration is all-or-nothing: the first rule that cannot be executed
    deterministically aborts registration and no rule from the set is
    retained.

    :param dataset_id: non-empty dataset identifier string; echoed into
        every result.
    :param rules: non-empty list of rule objects, each with exactly the
        keys ``rule_id`` (non-empty unique string), ``fields`` (non-empty
        list of distinct non-empty field names the rule relates),
        ``severity`` (one of ``error`` / ``warning`` / ``info``) and
        ``conditions`` (non-empty list; every condition must reference
        fields declared in ``fields``).
    :returns: ``{"dataset_id": ..., "rules": [compiled rules]}`` preserving
        the input registration order.
    :raises ValueError: :class:`CompositeRuleSetError`
        (``INVALID_RULE_SET``), :class:`DuplicateRuleIdError`
        (``DUPLICATE_RULE_ID``), :class:`InvalidSeverityError`
        (``INVALID_SEVERITY``), :class:`UnsupportedCompositeConditionError`
        (``UNSUPPORTED_COMPOSITE_CONDITION``) or
        :class:`InvalidCompositeRuleError` (``INVALID_COMPOSITE_RULE``).
    """
    if not isinstance(dataset_id, str) or not dataset_id:
        raise CompositeRuleSetError(
            "dataset_id must be a non-empty string when composite rules "
            "are registered"
        )
    if not isinstance(rules, list) or not rules:
        raise CompositeRuleSetError(
            "composite rules must be a non-empty list"
        )

    compiled: List[Dict[str, Any]] = []
    seen_ids: Set[str] = set()
    for rule in rules:
        compiled_rule = _compile_rule(rule, seen_ids)
        seen_ids.add(compiled_rule["rule_id"])
        compiled.append(compiled_rule)

    return {"dataset_id": dataset_id, "rules": compiled}


def _condition_satisfied(condition: Dict[str, Any], record: Dict[str, Any]) -> bool:
    condition_type = condition["type"]

    if condition_type == CONDITION_EQUAL:
        return _json_equal(
            record[condition["left_field"]], record[condition["right_field"]]
        )

    if condition_type == CONDITION_NOT_EQUAL:
        return not _json_equal(
            record[condition["left_field"]], record[condition["right_field"]]
        )

    if condition_type == CONDITION_DATE_BEFORE:
        earlier = _parse_date(record[condition["earlier_field"]])
        later = _parse_date(record[condition["later_field"]])
        if earlier is None or later is None:
            # Illegal date values cannot satisfy a date-order constraint.
            return False
        return earlier < later

    # required_when: while the prerequisite holds, the required field
    # must be present (guaranteed by the field-set check) and non-null.
    if not _json_equal(record[condition["when_field"]], condition["equals"]):
        return True
    return record[condition["required_field"]] is not None


def _record_id(record: Dict[str, Any]) -> Any:
    return record["id"] if "id" in record else None


def _evaluate_one(
    record: Dict[str, Any],
    index: int,
    rule: Dict[str, Any],
    dataset_id: str,
) -> Dict[str, Any]:
    fields = rule["fields"]
    missing = [field for field in fields if field not in record]
    if missing:
        status = STATUS_SKIPPED_MISSING_FIELD
        condition_results = [
            {"type": condition["type"], "satisfied": None}
            for condition in rule["conditions"]
        ]
    else:
        condition_results = []
        satisfied_all = True
        for condition in rule["conditions"]:
            satisfied = _condition_satisfied(condition, record)
            condition_results.append(
                {"type": condition["type"], "satisfied": satisfied}
            )
            if not satisfied:
                satisfied_all = False
        status = STATUS_PASSED if satisfied_all else STATUS_FAILED

    return {
        "dataset_id": dataset_id,
        "record_index": index,
        "record_id": _record_id(record),
        "rule_id": rule["rule_id"],
        "fields": list(fields),
        "status": status,
        "severity": rule["severity"],
        "context": {
            # Snapshot only the participating fields, in registration
            # order, so downstream consumers see immutable evidence.
            "field_values": {
                field: record.get(field)
                for field in fields
                if field in record
            },
            "missing_fields": missing,
            "conditions": condition_results,
        },
    }


def _resolve_record_refs(
    record_refs: Any, records: List[Dict[str, Any]]
) -> List[Tuple[int, Dict[str, Any]]]:
    """Resolve record locators to ``(index, record)`` pairs.

    First occurrence wins (duplicate locators are deduplicated); the
    original reference order is preserved.
    """
    if not isinstance(record_refs, list):
        raise InvalidRecordReferenceError("record_refs must be a list")

    resolved: List[Tuple[int, Dict[str, Any]]] = []
    seen_indices: Set[int] = set()
    for ref_index, ref in enumerate(record_refs):
        where = f"record_refs[{ref_index}]"
        if not isinstance(ref, dict):
            raise InvalidRecordReferenceError(f"{where} must be an object")
        keys = set(ref)
        if not keys or not keys <= {"record_index", "record_id"}:
            raise InvalidRecordReferenceError(
                f"{where} may only contain 'record_index' and/or 'record_id'"
            )

        if "record_index" in ref:
            record_index = ref["record_index"]
            # bool is a subclass of int but JSON true/false are not indexes.
            if isinstance(record_index, bool) or not isinstance(record_index, int):
                raise InvalidRecordReferenceError(
                    f"{where}.record_index must be an integer"
                )
            if not 0 <= record_index < len(records):
                raise InvalidRecordReferenceError(
                    f"{where}.record_index is out of range: {record_index}"
                )
            index = record_index
        else:
            index = -1
            for candidate_index, candidate in enumerate(records):
                if "id" in candidate and candidate["id"] == ref["record_id"]:
                    index = candidate_index
                    break
            if index < 0:
                raise InvalidRecordReferenceError(
                    f"{where}.record_id does not match any record: "
                    f"{ref['record_id']!r}"
                )

        if "record_id" in ref:
            record_id = ref["record_id"]
            if not isinstance(record_id, str) or not record_id:
                raise InvalidRecordReferenceError(
                    f"{where}.record_id must be a non-empty string"
                )
            record = records[index]
            if record.get("id") != record_id or "id" not in record:
                raise InvalidRecordReferenceError(
                    f"{where} locates record index {index} but its record id "
                    f"is {record.get('id')!r}, not {record_id!r}"
                )

        if index not in seen_indices:
            seen_indices.add(index)
            resolved.append((index, records[index]))

    return resolved


def evaluate_composite_rules(
    records: Any,
    rule_set: Dict[str, Any],
    record_refs: Any = None,
) -> List[Dict[str, Any]]:
    """Evaluate registered composite rules over records.

    Records are read one by one; within one record every rule is evaluated
    in registration order. A record missing any field of a rule's target
    field set yields :data:`STATUS_SKIPPED_MISSING_FIELD` for that rule;
    the rule is neither passed nor failed for that record, and other rules
    keep executing.

    :param records: list of JSON object records.
    :param rule_set: output of :func:`register_composite_rules`.
    :param record_refs: optional list of locators (``{"record_index": i}``
        and/or ``{"record_id": ...}``) restricting evaluation to specific
        records; a locator that cannot be resolved raises
        :class:`InvalidRecordReferenceError`. When omitted every record is
        evaluated.
    :returns: complete result list, ordered by record order then by rule
        registration order.
    """
    if not isinstance(records, list):
        raise InvalidRecordReferenceError("records must be a list")
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            raise InvalidRecordReferenceError(
                f"records[{index}] must be a JSON object"
            )

    dataset_id = rule_set["dataset_id"]
    rules = rule_set["rules"]

    if record_refs is None:
        selected: List[Tuple[int, Dict[str, Any]]] = list(enumerate(records))
    else:
        selected = _resolve_record_refs(record_refs, records)

    results: List[Dict[str, Any]] = []
    for index, record in selected:
        for rule in rules:
            results.append(_evaluate_one(record, index, rule, dataset_id))
    return results


def query_composite_results(
    results: Any,
    rule_id: Any = None,
    severity: Any = None,
    record_index: Any = None,
    record_id: Any = None,
) -> Dict[str, Any]:
    """Filter complete composite results without changing their order.

    Every supplied filter is AND-combined; omitted filters do not restrict.

    :param results: result list produced by
        :func:`evaluate_composite_rules` (or a previously filtered one).
    :param rule_id: keep results of this rule id.
    :param severity: keep results with this severity level.
    :param record_index: keep results located at this record index.
    :param record_id: keep results located at this record id.
    :returns: ``{"count": n, "results": [...]}`` in the original stable
        order.
    """
    if not isinstance(results, list):
        raise ValueError("results must be a list")
    if rule_id is not None and not isinstance(rule_id, str):
        raise ValueError("rule_id filter must be a string")
    if severity is not None and not isinstance(severity, str):
        raise ValueError("severity filter must be a string")
    if record_index is not None and (
        isinstance(record_index, bool) or not isinstance(record_index, int)
    ):
        raise ValueError("record_index filter must be an integer")
    if record_id is not None and not isinstance(record_id, str):
        raise ValueError("record_id filter must be a string")

    filtered = []
    for result in results:
        if not isinstance(result, dict):
            raise ValueError("each result must be an object")
        if rule_id is not None and result.get("rule_id") != rule_id:
            continue
        if severity is not None and result.get("severity") != severity:
            continue
        if (
            record_index is not None
            and result.get("record_index") != record_index
        ):
            continue
        if record_id is not None and result.get("record_id") != record_id:
            continue
        filtered.append(result)

    return {"count": len(filtered), "results": filtered}


def sample_id_for_record(result: Dict[str, Any]) -> str:
    """Derive the stable anomaly-sample id used by the downstream adapters.

    A record's ``id`` is used when it is a non-empty string, otherwise a
    deterministic ``"record:<index>"`` locator. Evaluation results carry
    the same ``record_index`` / ``record_id`` pair, so jumping from a
    correlated anomaly back to the validation result resolves to the same
    record and participating fields.
    """
    record_id = result.get("record_id")
    if isinstance(record_id, str) and record_id:
        return record_id
    return f"record:{result['record_index']}"


def composite_results_to_correlation(
    results: Any,
) -> List[Dict[str, Any]]:
    """Adapt FAILED composite results to ``correlate_violations`` input.

    Emits one correlation result row per ``(failed rule result,
    participating field)`` with ``violated`` true and that field's value,
    so the existing cross-rule / field-lineage correlation consumes
    cross-field anomalies unchanged. PASSED and skipped results produce no
    rows.
    """
    if not isinstance(results, list):
        raise ValueError("results must be a list")

    rows: List[Dict[str, Any]] = []
    for result in results:
        if not isinstance(result, dict):
            raise ValueError("each result must be an object")
        if result.get("status") != STATUS_FAILED:
            continue
        sample_id = sample_id_for_record(result)
        values = result.get("context", {}).get("field_values", {})
        for field in result["fields"]:
            rows.append(
                {
                    "rule_id": result["rule_id"],
                    "dataset_id": result["dataset_id"],
                    "field_id": field,
                    "sample_id": sample_id,
                    "violated": True,
                    "value": values.get(field),
                }
            )
    return rows


def composite_results_to_impact_inputs(
    results: Any,
) -> Dict[str, Any]:
    """Adapt FAILED composite results to ``analyze_field_impacts`` inputs.

    :returns: ``{"validationResults": [...], "anomalySamples": {...}}``.
        Each failed rule becomes one ``failed`` validation result touching
        every participating ``{dataset, field}``; every failed record
        becomes a locatable anomaly sample keyed by the same sample id the
        correlation adapter uses, carrying the participating field values.
        The caller supplies ``datasets``, ``lineageEdges`` and
        ``seedFields`` to complete the impact-analysis payload.
    """
    if not isinstance(results, list):
        raise ValueError("results must be a list")

    rules_in_order: List[str] = []
    rule_fields: Dict[str, Set[Tuple[str, str]]] = {}
    rule_samples: Dict[str, List[str]] = {}
    samples: Dict[str, Dict[str, Any]] = {}

    for result in results:
        if not isinstance(result, dict):
            raise ValueError("each result must be an object")
        if result.get("status") != STATUS_FAILED:
            continue

        rule_id = result["rule_id"]
        if rule_id not in rule_fields:
            rules_in_order.append(rule_id)
            rule_fields[rule_id] = set()
            rule_samples[rule_id] = []
        dataset_id = result["dataset_id"]
        for field in result["fields"]:
            rule_fields[rule_id].add((dataset_id, field))

        sample_id = sample_id_for_record(result)
        if sample_id not in rule_samples[rule_id]:
            rule_samples[rule_id].append(sample_id)
        if sample_id not in samples:
            samples[sample_id] = {
                "dataset": dataset_id,
                "fieldValues": dict(
                    result.get("context", {}).get("field_values", {})
                ),
            }

    validation_results = [
        {
            "ruleId": rule_id,
            "status": "failed",
            "fields": [
                {"dataset": dataset, "field": field}
                for dataset, field in sorted(rule_fields[rule_id])
            ],
            "failedSampleIds": list(rule_samples[rule_id]),
        }
        for rule_id in rules_in_order
    ]

    return {
        "validationResults": validation_results,
        "anomalySamples": samples,
    }

